end

function utils.is_arweave_address(address)
    if type(address) ~= "string" then
        return false
    end
    -- Arweave addresses are 43 characters long and base64url encoded
    return string.len(address) == 43 and string.match(address, "^[A-Za-z0-9_-]+$") ~= nil
end

return utils
end

